    'faq.q1': 'Is Al Shujaiat Foundation a registered charitable organization?',
    'faq.a1': 'Yes. Al Shujaiat Foundation is a legally registered non-profit charitable trust in Jammu & Kashmir and enrolled on NITI Aayog NGO-DARPAN under Unique ID / Registration Number JK/2018/0190361. Donations are recognized for tax exemption under Section 80G (Reg: DEL-AE28396-27022018/9728) and Section 12A (Reg: DEL-AR26932-27022018/8830) of the Indian Income Tax Act.',
    'faq.q2': 'How are project funding numbers calculated on this platform?',
    'faq.a2': 'The frontend is never the source of truth for financial totals. Project funding progress (Total Need, Raised, Remaining, and Donor Count) is calculated dynamically and strictly from verified successful payments minus approved refunds processed by our finance team.',
    'faq.q3': 'Will I receive an official tax deduction receipt after donating?',
    'faq.a3': 'Yes. The moment your transaction is confirmed, an official computer-generated PDF tax receipt is generated containing unique serial numbers, statutory registration numbers, transaction IDs, and authorized digital verification stamps. You can download it immediately or retrieve it anytime from your Donor Portal.',
    'faq.q4': 'Can international donors contribute in USD, GBP, EUR, or other currencies?',
    'faq.a4': 'Absolutely. We accept international payments via Stripe (supporting Visa, Mastercard, American Express, Apple Pay) and direct international wire transfers. Our platform supports independent language and currency selection.',
    'faq.q5': 'How do monthly and yearly recurring subscriptions work?',
    'faq.a5': 'Recurring donations are real payment subscriptions managed through secure payment gateway tokens. Donors have full autonomous control to view upcoming billing dates, pause, resume, retry failed charges, or cancel subscriptions anytime in the Donor Dashboard.',
    'faq.q6': 'How do I cancel or modify my recurring donation subscription?',
    'faq.q7': 'What happens if a project or emergency campaign exceeds its target goal?',
    'faq.a7': 'Surplus funds are allocated to adjacent regional emergency needs within the same program pillar (e.g. surplus water well funds are directed to nearby mountain filtration repairs in Baramulla or Kupwara), with full audit log disclosure in our annual financial report.',
    'faq.q8': 'Can I request a physical signed and stamped Section 80G certificate by post?',
    'faq.a8': 'Yes. While digital receipts with QR verification are instant and legally valid under Indian IT rules, institutional or individual donors requiring hard copies with wet ink stamps can request dispatch via India Post Speed Post by submitting a ticket through our Contact Desk.',
    'faq.q9': 'Is my personal and financial information shared with third parties?',
    'faq.a9': 'Never. We strictly uphold donor confidentiality. We do not sell, trade, or share donor contact information. Payment processing is tokenized end-to-end through PCI-DSS Level 1 certified gateways (Stripe & Razorpay); our servers never store raw credit card or bank credentials.',
    'faq.q10': 'How quickly are emergency relief funds deployed during winter disasters?',
    'faq.a10': 'During avalanches, flash floods, or severe winter blockades, emergency relief kits (food rations, thermal blankets, kangri heating units, and medical supplies) are mobilized within 6 hours from our prepositioned disaster response warehouses in Srinagar and north Kashmir.',
    'faq.q11': 'How are volunteer applicants vetted and assigned identity badges?',
    'faq.q12': 'Can I visit project sites in Jammu & Kashmir in person?',
    'faq.a12': 'Yes. We welcome international donors, researchers, and volunteers to visit our community filtration plants and schools. Please submit a volunteer application or request a field visit through our Contact Desk at least 14 days in advance to arrange logistics.',
    'faq.q13': 'What is your refund and transaction reversal policy?',
    'faq.a13': 'If a duplicate charge occurs or an erroneous donation is made, donors may request a full refund within 15 calendar days of the transaction date. Approved refunds are credited back to the original payment source within 5 to 7 business days.',
    'faq.q14': 'Are contributions eligible for Zakat and Sadaqah allocation?',
    'faq.q15': 'Is Al Shujaiat Foundation eligible for Corporate CSR partnerships in India?',
    'faq.a15': 'Yes. The foundation is fully compliant with Section 135 of the Companies Act, 2013, and holds valid MCA CSR-1 registration. We partner with public and private sector enterprises for targeted healthcare, clean water, and educational infrastructure CSR projects.',
