    'news.news_001.title': 'अल शुजाइत फाउंडेशन ने उत्तरी पहाड़ी क्षेत्र में 24वें सौर जल शोधन संयंत्र का उद्घाटन किया',
    'news.news_001.content': 'अल शुजाइत फाउंडेशन जम्मू और कश्मीर ने स्वच्छ जल पहल के तहत अपने 24वें सौर-संचालित गहरे जल शोधन संयंत्र की स्थापना की घोषणा की, जो प्रतिदिन 20,000 लीटर शुद्ध जल निःशुल्क प्रदान करता है।',
