    'faq.q1': 'क्या अल शुजाइत फाउंडेशन एक पंजीकृत धर्मार्थ संस्था है?',
    'faq.a1': 'हाँ। अल शुजाइत फाउंडेशन जम्मू और कश्मीर में पंजीकृत गैर-लाभकारी ट्रस्ट है, नीति आयोग एनजीओ दर्पण पर JK/2018/0190361 के तहत पंजीकृत है तथा आयकर अधिनियम की धारा 80G और 12A के तहत कर छूट प्राप्त है।',
    'faq.q2': 'मंच पर फंडिंग के आंकड़े कैसे आकलित होते हैं?',
    'faq.a2': 'आंकड़े पूरी तरह से सत्यापित सफल भुगतान और बैंक रिकॉर्ड्स से वास्तविक समय में अपडेट होते हैं।',
    'faq.q3': 'क्या दान के बाद आधिकारिक कर रसीद प्राप्त होगी?',
    'faq.a3': 'हाँ, भुगतान की पुष्टि होते ही सिस्टम डिजिटल पीडीएफ रसीद जारी करता है जिसमें कानूनी पंजीकरण और सत्यापन क्यूआर कोड होता है।',
    'faq.q4': 'क्या विदेशी दाता अन्य मुद्राओं (USD, EUR, आदि) में दान कर सकते हैं?',
    'faq.a4': 'बिल्कुल, हम स्ट्राइप और बैंक वायर के जरिए अंतर्राष्ट्रीय दान स्वीकार करते हैं।',
    'faq.q5': 'मासिक और वार्षिक आवर्ती सदस्यताएँ कैसे काम करती हैं?',
    'faq.a5': 'दाता अपने डैशबोर्ड से किसी भी समय अपनी आवर्ती योजना को प्रबंधित या रद्द कर सकते हैं।',
    'faq.q6': 'मैं अपना मासिक दान कैसे संशोधित या रद्द करूँ?',
    'faq.q7': 'यदि परियोजना का वित्तीय लक्ष्य पूरा हो जाए तो क्या होता है?',
    'faq.a7': 'अतिरिक्त धनराशि उसी क्षेत्र की नजदीकी आपातकालीन जरूरतों में पूर्ण ऑडिट पारदर्शिता के साथ उपयोग की जाती है।',
    'faq.q8': 'क्या हस्ताक्षरित रसीद डाक द्वारा प्राप्त हो सकती है?',
    'faq.a8': 'हाँ, स्पीड पोस्ट द्वारा मुद्रित रसीद प्राप्त करने के लिए सहायता केंद्र पर अनुरोध किया जा सकता है।',
    'faq.q9': 'क्या दाताओं की व्यक्तिगत जानकारी सुरक्षित रहती है?',
    'faq.a9': 'पूर्णतः सुरक्षित। हम दाताओं की जानकारी कभी किसी तीसरे पक्ष के साथ साझा नहीं करते।',
    'faq.q10': 'आपदा के समय कितनी जल्दी राहत सामग्री पहुंचती है?',
    'faq.a10': 'सर्दियों में बर्फबारी या आपदा के समय 6 घंटे के भीतर आवश्यक सामग्री रवाना कर दी जाती है।',
    'faq.q11': 'स्वयंसेवकों का सत्यापन और पहचान पत्र कैसे जारी होते हैं?',
    'faq.q12': 'क्या मैं जम्मू और कश्मीर में परियोजनाओं का दौरा कर सकता हूँ?',
    'faq.a12': 'हाँ, पूर्व सूचना के साथ दाताओं और शोधकर्ताओं का स्थल भ्रमण स्वागत योग्य है।',
    'faq.q13': 'दान वापसी (रिफंड) की नीति क्या है?',
    'faq.a13': 'गलती से दोहरा भुगतान होने पर 15 दिनों के भीतर रिफंड का अनुरोध किया जा सकता है।',
    'faq.q14': 'क्या दान जकात और सदका के अंतर्गत मान्य हैं?',
    'faq.q15': 'क्या फाउंडेशन कॉर्पोरेट सीएसआर (CSR) साझेदारी के लिए पात्र है?',
    'faq.a15': 'हाँ, फाउंडेशन एमसीए सीएसआर-1 के तहत विधिवत पंजीकृत है।',
