    'faq.q1': 'کیا الشجاعت فاؤنڈیشن ایک رجسٹرڈ ادارہ ہے؟',
    'faq.a1': 'جی ہاں، الشجاعت فاؤنڈیشن جموں و کشمیر میں ایک باضابطہ رجسٹرڈ فلاحی ٹرسٹ ہے جو نیتی آیوگ این جی او درپن کے تحت رجسٹرڈ ہے اور انکم ٹیکس ایکٹ کی دفعہ 80G اور 12A کے تحت ٹیکس چھوٹ کا حامل ہے۔',
    'faq.q2': 'پلیٹ فارم پر فنڈنگ کے اعداد و شمار کیسے شمار ہوتے ہیں؟',
    'faq.a2': 'اعداد و شمار براہِ راست تصدیق شدہ مالیاتی ریکارڈز اور کامیاب بینک ٹرانزیکشنز سے حقیقی وقت میں تیار ہوتے ہیں۔',
    'faq.q3': 'کیا عطیہ کے بعد مجھے سرکاری رسید ملے گی؟',
    'faq.a3': 'جی ہاں، ادائیگی کی تصدیق ہوتے ہی خودکار طور پر سرکاری ڈیجیٹل پی ڈی ایف رسید جاری ہو جاتی ہے جس میں رجسٹریشن نمبر اور تصدیقی کیو آر کوڈ موجود ہوتا ہے۔',
    'faq.q4': 'کیا بین الاقوامی عطیہ دہندگان مختلف کرنسیوں میں عطیہ دے سکتے ہیں؟',
    'faq.a4': 'جی ہاں، ہم اسٹرائپ اور بینک وائر کے ذریعے امریکی ڈالر، پاؤنڈ، یورو اور دیگر کرنسیوں میں عطیات قبول کرتے ہیں۔',
    'faq.q5': 'ماہانہ اور سالانہ سبسکرپشنز کیسے کام کرتی ہیں؟',
    'faq.a5': 'ڈونر اپنے ڈیش بورڈ سے کسی بھی وقت سبسکرپشن کا انتظام، توقف یا منسوخ کر سکتے ہیں۔',
    'faq.q6': 'میں اپنے ماہانہ عطیے کو کیسے تبدیل یا منسوخ کر سکتا ہوں؟',
    'faq.q7': 'اگر کسی پروجیکٹ کا ہدف مکمل ہو جائے تو اضافی فنڈز کا کیا ہوتا ہے؟',
    'faq.a7': 'اضافی فنڈز اسی شعبے کی قریبی ہنگامی ضروریات کے لیے مکمل آڈٹ شفافیت کے ساتھ استعمال کیے جاتے ہیں۔',
    'faq.q8': 'کیا دستخط شدہ کاغذی رسید بذریعہ ڈاک حاصل کی جا سکتی ہے؟',
    'faq.a8': 'جی ہاں، ڈونر سپورٹ ڈیسک پر درخواست دے کر اسپیڈ پوسٹ کے ذریعے کاغذی رسید حاصل کی جا سکتی ہے۔',
    'faq.q9': 'کیا ڈونر کی ذاتی معلومات محفوظ رہتی ہیں؟',
    'faq.a9': 'بالکل، ہم ڈونر کی رازداری کا مکمل احترام کرتے ہیں اور ادائیگیاں اعلیٰ ترین حفاظتی معیارات کے تحت پروسیس ہوتی ہیں۔',
    'faq.q10': 'ہنگامی حالات میں کتنی جلدی امداد پہنچائی جاتی ہے؟',
    'faq.a10': 'سردیوں میں برفباری یا آفات کے وقت ہمارے ویئر ہاؤسز سے 6 گھنٹے کے اندر اندر امدادی سامان روانہ کر دیا جاتا ہے۔',
    'faq.q11': 'رضاکاروں کی تصدیق اور شناختی کارڈ کیسے جاری ہوتے ہیں؟',
    'faq.q12': 'کیا میں جموں و کشمیر میں فاؤنڈیشن کے پروجیکٹس کا دورہ کر سکتا ہوں؟',
