    'faq.q1': 'هل مؤسسة الشجاعت منظمة خيرية مسجلة رسمياً؟',
    'faq.a1': 'نعم. مؤسسة الشجاعت هي صندوق خيري غير ربحي مسجل رسمياً في جامو وكشمير ومدرج في بوابة داربان الحكومية بالمعرف JK/2018/0190361، ومعفى بموجب المادتين 80G و 12A من قانون ضريبة الدخل الهندي.',
    'faq.q2': 'كيف يتم حساب مبالغ تمويل المشاريع على المنصة؟',
    'faq.a2': 'تُحسب بيانات التمويل بدقة وشفافية من واقع المدفوعات المؤكدة فقط مخصوماً منها أي مبالغ مستردة معتمدة، دون أي تعديلات يدوية.',
    'faq.q3': 'هل سأحصل على إيصال رسمي للإعفاء الضريبي بعد التبرع؟',
    'faq.a3': 'نعم فور إتمام المعاملة، يصدر النظام تلقائياً إيصالاً إلكترونياً رسمياً بصيغة PDF يحتوي على أرقام التسجيل النظامية والختم الرقمي المعتمد ورمز التحقق QR.',
    'faq.q4': 'هل يمكن للمتبرعين الدوليين التبرع بعملات أخرى مثل الدولار واليورو والجنيه؟',
    'faq.a4': 'بالتأكيد. نقبل الدفع ببطاقات الائتمان الدولية عبر Stripe والتحويلات المصرفية المباشرة مع إمكانية التبديل بين اللغات والعملات.',
    'faq.q5': 'كيف تعمل الاشتراكات الشهرية والتبرعات الدورية؟',
    'faq.a5': 'يتم إدارة الاشتراكات بأمان عبر بوابات الدفع المشفرة، مع تحكم كامل للمتبرع لإيقاف أو تجديد أو تعديل خطته في أي وقت من لوحة التحكم.',
    'faq.q6': 'كيف يمكنني تعديل أو إلغاء اشتراكي في التبرع الدوري؟',
    'faq.q7': 'ماذا يحدث إذا تجاوز المشروع أو الحملة هدفها المالي المحدد؟',
    'faq.a7': 'يتم توجيه الفائض إلى أقرب احتياج إنساني طارئ في نفس المجال الجغرافي والبرامجي مع الإفصاح الكامل في تقرير التدقيق السنوي.',
    'faq.q8': 'هل يمكنني طلب إيصال ورقي مختوم بالبريد؟',
    'faq.a8': 'نعم بالإضافة للإيصال الرقمي الفوري، يمكن طلب نسخة ورقية مختومة بالبريد السريع عبر التواصل مع مكتب الدعم.',
    'faq.q9': 'هل تتم مشاركة بياناتي الشخصية أو المالية مع أي طرف ثالث؟',
    'faq.a9': 'على الإطلاق. نحن نلتزم بالسرية التامة للبيانات، وتتم المعالجة عبر بوابات معتمدة متوافقة مع معايير PCI-DSS دون تخزين بيانات البطاقات.',
    'faq.q10': 'ما هي سرعة الاستجابة الميدانية في الكوارث الشتوية؟',
    'faq.a10': 'يتم تحريك قوافل الإغاثة وتوزيع أطقم التدفئة والغذاء خلال 6 ساعات من مستودعات الطوارئ المجهزة مسبقاً في سريناغار وشمال كشمير.',
    'faq.q11': 'كيف يتم فحص طلبات التطوع وإصدار بطاقات الهوية الرسمية؟',
    'faq.q12': 'هل يمكنني زيارة مواقع المشاريع في جامو وكشمير شخصياً؟',
    'faq.a12': 'نعم نرحب بزيارات المتبرعين والباحثين للمحطات والمدارس بالتنسيق المسبق مع مكتب الاتصال قبل 14 يوماً لترتيب الخدمات اللوجستية.',
    'faq.q13': 'ما هي سياسة استرداد وإلغاء التبرعات؟',
    'faq.a13': 'في حال حدوث خطأ أو تكرار الدفع، يمكن طلب استرداد المبلغ خلال 15 يوماً وتتم إعادة الأموال إلى المصدر خلال 5 إلى 7 أيام عمل.',
    'faq.q14': 'هل التبرعات متوافقة مع مصارف الزكاة والصدقات؟',
    'faq.q15': 'هل المؤسسة مؤهلة لشراكات المسؤولية الاجتماعية للشركات (CSR)؟',
